    "VOYAGE_API_KEY",
    "VOYAGE_API_KEY_RUST",
];

fn voyage_key_present() -> bool {
    KEY_VARS
        .iter()
        .any(|var| std::env::var(var).is_ok_and(|value| !value.trim().is_empty()))
}

